assert len(records)==14
changes=[]
for r in records:
 assert len(r['description'].split())>=110,(r['id'],len(r['description'].split()))
 changes += [change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))]
write_revision(3,changes,'2026-10-17 popular-franchise best-guess pass: eight Star Trek societies plus The Jetsons, the Citadel of Ricks, Halo’s Forerunners and three DC futures. Explicit admission uncertainty and zero-variant analogies replace earlier lore-gap omissions.')
